-- Update ConsultasUsadas and ProyectosCreados with random dummy data
UPDATE Usuarios SET ConsultasUsadas = ABS(CHECKSUM(NEWID()) % 15) + 1, ProyectosCreados = ABS(CHECKSUM(NEWID()) % 5) + 1 WHERE IdUsuario IN (SELECT IdUsuario FROM Usuarios);
